// Hash function for deterministic noise
    float hash(vec2 p) {
        // A simple 2D hash function
        return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
    }

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Screen resolution
    vec2 resolution = iResolution.xy;

    // Uniform to control the scale of the noise
    float scale = 1.0; // Adjust or expose this as a uniform

    // Scale the coordinates
    vec2 scaledCoord = floor(fragCoord / scale);

    // Generate noise based on scaled coordinates
    float noise = hash(scaledCoord);

    // Output the noise as grayscale
    fragColor = vec4(vec3(noise), 1.0);
}
